import React, { useEffect, useState, useContext } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { Container, Row, Col, Button, Card, CardBody } from 'reactstrap';
import { BASE_URL } from '../utils/config';
import { AuthContext } from '../context/AuthContext';

const Voucher = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const { user } = useContext(AuthContext);
  const [voucher, setVoucher] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchVoucher = async () => {
      setLoading(true);
      setError(null);
      try {
        const token = localStorage.getItem('token');
        const res = await fetch(`${BASE_URL}/booking/${id}/voucher`, {
          headers: {
            'Content-Type': 'application/json',
            Authorization: `Bearer ${token}`,
          },
        });
        const result = await res.json();
        if (!res.ok) {
          setError(result.message || 'Không lấy được voucher');
          return;
        }
        setVoucher(result.data);
      } catch (err) {
        setError('Lỗi kết nối');
      } finally {
        setLoading(false);
      }
    };

    if (user) {
      fetchVoucher();
    }
  }, [id, user]);

  return (
    <section className="pt-5">
      <Container>
        <Row>
          <Col lg='10' className='m-auto'>
            <div className='shadow-lg rounded p-4 bg-white'>
              <Button color='secondary' outline onClick={() => navigate(-1)}>
                Quay lại
              </Button>
              <h2 className='my-4'>Voucher Tour</h2>
              {loading && <p>Đang tải voucher...</p>}
              {error && <p className='text-danger'>{error}</p>}
              {!loading && !error && voucher && (
                <Card className='border-0 shadow-sm'>
                  <CardBody>
                    <h4 className='mb-3'>Mã voucher: <strong>{voucher.voucherCode}</strong></h4>
                    <p><strong>Tên khách:</strong> {voucher.details?.fullName}</p>
                    <p><strong>Tên tour:</strong> {voucher.details?.tourName}</p>
                    <p><strong>Ngày khởi hành:</strong> {voucher.details?.bookingAt ? new Date(voucher.details.bookingAt).toLocaleDateString('vi-VN') : 'N/A'}</p>
                    <p><strong>Tổng tiền:</strong> {(voucher.details?.totalPrice || 0).toLocaleString('vi-VN')}đ</p>
                    <p><strong>Hiệu lực đến:</strong> {voucher.validUntil ? new Date(voucher.validUntil).toLocaleDateString('vi-VN') : 'N/A'}</p>
                    <div className='mt-4 p-3 bg-light rounded'>
                      <p><strong>Trạng thái voucher:</strong> {voucher.status}</p>
                      <p>Voucher này dùng để xác nhận khi đến điểm khởi hành tour.</p>
                    </div>
                  </CardBody>
                </Card>
              )}
            </div>
          </Col>
        </Row>
      </Container>
    </section>
  );
};

export default Voucher;
